gameforge["ro"][5686] = "Gaseste pe Generalul Gnoll. El are scrisoarea! "
gameforge["ro"][5687] = "Nu avem timp de pierdut. Te rog grabeste-te si[ENTER]adu-mi scrisoarea. "
gameforge["ro"][5688] = "Ai gasit Scrisoarea Gnoll. "
gameforge["ro"][5689] = "Adu-o Amiralului Angmur. "
gameforge["ro"][5690] = "Vorbeste cu Amiralul Angmur. "
gameforge["ro"][5691] = "Ai scrisoarea! In sfarsit niste vesti bune nu-i[ENTER]asa?[ENTER]Hmm...[ENTER]Nu pot citi nici un cuvant. Scrisoarea pare a fi[ENTER]criptata. Savantul nostru stie criptologie. O[ENTER]sa-l caut imediat. De indata ce aflu mai multe te[ENTER]anunt si pe tine. "
gameforge["ro"][5692] = " "
gameforge["ro"][5693] = " "
gameforge["ro"][5694] = "Scrisoarea Gnoll II "
gameforge["ro"][5695] = "Amiralul Angmur te cauta. Pare sa fie ceva[ENTER]important. Vezi ce doreste. "
gameforge["ro"][5696] = "Scrisoarea criptata conºine doua pagini. Mesajul[ENTER]poate fi decodat doar atunci când cele doua foi[ENTER]sunt aoezate una peste alta. Lord Gnoll are a[ENTER]doua foaie.[ENTER]Ne poºi ajuta? "
gameforge["ro"][5697] = "Desigur. "
gameforge["ro"][5698] = "Multumesc. Ajutorul tau este nemasurat! "
gameforge["ro"][5699] = "Scrisoarea Gnoll II "
gameforge["ro"][5700] = "Gaseote a doua foaie de la Scrisoarea Gnoll! O[ENTER]vei lua de la Lord Gnoll. "
gameforge["ro"][5701] = "Timpul se scurge! Grabeote-te oi gaseote a doua[ENTER]foaie a scrisorii. "
gameforge["ro"][5702] = "Ai gasit a doua foaie. Du-o Amiralului Angmur. "
gameforge["ro"][5703] = "Excelent, acum putem sa decodam mesajul: Hmm,[ENTER]pare a fi vorba despre dragoni care dorm adanc in[ENTER]inima lumii. Se vorbeste despre o metoda prin[ENTER]care ii poti trezi si sa-i innebunesti.[ENTER]Oh ho! Asta nu suna prea bine... "
gameforge["ro"][5704] = " "
gameforge["ro"][5705] = "Se pare ca Manticore oi Tabara Tâlharilor Rooii[ENTER]au primit de asemenea scrisoarea. O sa aflu mai[ENTER]multe despre aceasta otire oi te voi chema. "
gameforge["ro"][5706] = "Amiralul Angmur are o misiune pentru tine. "
gameforge["ro"][5707] = "Manticores "
gameforge["ro"][5708] = "Amiralul Angmur are o misiune pentru tine. "
gameforge["ro"][5709] = "Bun, esti aici! Informatiile noastre despre[ENTER]Manticores sunt destul de vechi. Trebuie sa aflam[ENTER]cat de puternice sunt in prezent fortele lor. "
gameforge["ro"][5710] = "Poti merge sa-i spionezi? Tabara lor nu este[ENTER]foarte departe de aici. "
gameforge["ro"][5711] = "Sigur. Ce pot face? "
gameforge["ro"][5712] = "Învinge 50 Manticore Razboinic, 40 Manticore[ENTER]Soldat, 20 Manticore Calau, precum oi pe[ENTER]Generalul Cor de 10 ori.[ENTER]Apoi raporteaza-mi mie. "
gameforge["ro"][5713] = "Ramas "
gameforge["ro"][5714] = "%s: %d[ENTER]%s: %d "
gameforge["ro"][5715] = "Informatia pe care ne-ai adus-o nu este[ENTER]suficienta. Trebuie sa aflii mai mult. "
gameforge["ro"][5716] = "Ai strans toate informatiile cerute de la[ENTER]manticores. "
gameforge["ro"][5717] = "Raporteaza cele aflate Amiralului Angmur. "
gameforge["ro"][5718] = "Ai terminat misiunea? Foarte bine. Atunci[ENTER]raporteaza-mi tot ce stii despre aceasta[ENTER]situatie. "
gameforge["ro"][5719] = "Raspândirea Manticores nu este deosebit de mare.[ENTER]Tu ai avantajul numeric.[ENTER]Dar razboinicii lor sunt bine antrenaºi oi extrem[ENTER]de duri.[ENTER]Îºi recomand sa consolidezi zidul din jurul[ENTER]fortareºei pentru o aparare mai buna. Acesta nu[ENTER]va rezista unui asalt Manticore. "
gameforge["ro"][5720] = "Exact, aceasta este informatia de care avem[ENTER]nevoie. Voi lua in considerare sfatul tau de a[ENTER]consolida zidul. Te rog primeste asta drept[ENTER]recompensa. "
gameforge["ro"][5721] = "Vorbeste cu Amiralul Angmur "
gameforge["ro"][5722] = "Fortele Maticore "
gameforge["ro"][5723] = "Învinge 50 Manticore Razboinic, 40 Manticore[ENTER]Soldat, 20 Manticore Calau, precum oi pe[ENTER]Generalul Cor de 10 ori. "
gameforge["ro"][5724] = "Consolideaza Zidul I "
gameforge["ro"][5725] = "Amiralul Angmur te cauta. Pare sa fie ceva[ENTER]important. Mergi la el imediat. "
gameforge["ro"][5726] = "Ah, aici erai. Ai avut dreptate, zidul nostru nu[ENTER]ar fi rezistat nici macar unui atac. Dar nu avem[ENTER]materialele necesare pentru a-l intari. "
gameforge["ro"][5727] = "Avem nevoie de caramida de Lut si Nisip Fin. Ne[ENTER]poti aduce aceste materiale? "
