gameforge["ro"][5797] = "Ai gasit o doza de Praf Carapax. "
gameforge["ro"][5798] = "Adu-o la Yon-I-Walker. "
gameforge["ro"][5799] = "Otravitoare! "
gameforge["ro"][5800] = "Amiralul Angmur are nevoie urgent de tine.[ENTER]Mergi si afla ce doreste. "
