gameforge["ro"][10521] = "Gold Frog Event: unless you have their permission. "
gameforge["ro"][10522] = "Hexagonal Chest Event "
gameforge["ro"][10523] = "One of the traditions in Chinese New year is the gifting[ENTER]and the wishes of good fortune. In Chinese culture, the[ENTER]six sides of the Hexagonal Box represent these wishes. "
gameforge["ro"][10524] = "Collect Hexagonal Boxes from any monster! Hexagonal[ENTER]boxes contain a random upgrade material.[ENTER][ENTER]Enjoy the treasure and it's contents! "
gameforge["ro"][10525] = "Metins Shower Event "
gameforge["ro"][10526] = "Metins Shower have landed in the Event Map.[ENTER]Metins are spawned on 3 different areas,[ENTER]each area holds Metins with similar levels. "
gameforge["ro"][10527] = "Metins Shower Event: You are not allowed to hunt down other players. "
gameforge["ro"][10528] = "Metins Shower Event: You are not allowed to steal other players' loot. "
