gameforge["ro"][10531] = "Metins Shower Event: unless you have their permission. "
gameforge["ro"][10532] = "Mining Event "
gameforge["ro"][10533] = "Mining Event is taking place on the Event Map.[ENTER]Veins are spawned on 3 different areas,[ENTER]each area holds veins with similar levels. "
gameforge["ro"][10534] = "Mining Event: You are not allowed to hunt down other players. "
gameforge["ro"][10535] = "Mining Event: You are not allowed to steal other players' loot. "
